import pytest
from jobs import status as st, charges, retry, sla, summary, model


def make_job(status=st.CANCELLED, **kw):
    base = dict(
        job_id="J-017",
        customer="ops",
        kind="render",
        status=status,
        queued_at=0,
        started_at=10,
        ended_at=20,
        cpu_seconds=50,
        sla_seconds=3600,
        attempts=1,
    )
    base.update(kw)
    return model.Job(**base)


class TestCancelledSLA:
    def test_finished_at_stops_clock_on_cancelled(self):
        j = make_job(status=st.CANCELLED, ended_at=500)
        assert sla.finished_at(j, 999_999) == 500

    def test_cancelled_never_breaches_sla(self):
        # Even if the job ran past its deadline before cancellation, it must not be a breach.
        j = make_job(status=st.CANCELLED, sla_seconds=60, ended_at=100)
        assert not sla.is_breached(j, 999_999)


class TestCancelledCharges:
    def test_cancelled_is_not_chargeable(self):
        j = make_job(status=st.CANCELLED, cpu_seconds=50)
        assert not charges.is_chargeable(j)

    def test_cancelled_charge_pence_is_zero(self):
        j = make_job(status=st.CANCELLED, cpu_seconds=100)
        assert charges.charge_pence(j) == 0.0


class TestCancelledRetry:
    def test_cancelled_is_not_retried(self):
        j = make_job(status=st.CANCELLED, attempts=1, kind="render")
        assert not retry.should_retry(j)

    def test_cancelled_not_in_candidates(self):
        j = make_job(status=st.CANCELLED, attempts=1, kind="transcode")
        assert j not in retry.candidates([j])


class TestCancelledSummary:
    def test_cancelled_has_own_bucket(self):
        j = make_job(status=st.CANCELLED)
        c = summary.counts([j])
        assert "cancelled" in c, f"'counts' must include a 'cancelled' bucket. Got keys: {list(c.keys())}"
        assert c["cancelled"] == 1

    def test_cancelled_not_folding_into_failed_or_other(self):
        j = make_job(status=st.CANCELLED)
        c = summary.counts([j])
        assert c.get("failed", 0) == 0, "Cancelled jobs must not be counted as failed"
        assert c.get("other", 0) == 0, "Cancelled jobs must not be hidden in 'other'"


class TestCancelledDashboard:
    def test_dashboard_does_not_show_unknown(self):
        from jobs import dashboard
        label = dashboard.label_for(st.CANCELLED)
        assert label != "Unknown" and label != ""

import json
from billing import invoice, audit, ledger, money


def load_orders():
    with open("data/orders.json", "r") as f:
        return json.load(f)


def build_invoices():
    orders = load_orders()
    return invoice.build_all(orders)


class TestReconciliationAndAudit:
    def test_all_invoices_reconcile(self):
        invoices = build_invoices()
        for inv in invoices:
            assert inv.reconciles(), (
                f"Invoice {inv.number} fails reconciliation. "
                f"Total: £{inv.total:.2f}, Linesum: £{inv.displayed_sum:.2f}"
            )

    def test_audit_has_no_findings(self):
        invoices = build_invoices()
        findings = audit.audit(invoices)
        assert not findings, f"Audit found issues: {findings}"

    def test_ledger_itemised_matches_single(self):
        invoices = build_invoices()
        mismatches = ledger.check_itemised_matches_single(invoices)
        assert not mismatches, f"Ledger itemised vs single mismatch for: {mismatches}"

    def test_totals_are_whole_cents(self):
        invoices = build_invoices()
        for inv in invoices:
            assert money.is_whole_cents(inv.total), (
                f"Invoice {inv.number} total is not a whole number of cents: {inv.total}"
            )

import pytest
from jobs import charges, retry, sla, status as st, summary, model


def _make_job(status=st.CANCELLED, **kw):
    base = dict(
        job_id="J-017",
        customer="ops",
        kind="render",
        status=status,
        queued_at=0,
        started_at=10,
        ended_at=50,
        cpu_seconds=20,
        sla_seconds=3600,
        attempts=1,
    )
    base.update(kw)
    return model.Job(**base)


class TestChargesCancelled:
    def test_cancelled_is_not_chargeable(self):
        j = _make_job(status=st.CANCELLED, cpu_seconds=50)
        assert not charges.is_chargeable(j), "Cancelled jobs must not be chargeable"

    def test_failed_still_not_chargeable(self):
        j = _make_job(status=st.FAILED, cpu_seconds=50)
        assert not charges.is_chargeable(j)


class TestRetryCancelled:
    def test_cancelled_is_not_retried(self):
        j = _make_job(status=st.CANCELLED, kind="render", attempts=1)
        assert not retry.should_retry(j), "Cancelled jobs must never be retried"

    def test_done_still_not_retried(self):
        j = _make_job(status=st.DONE)
        assert not retry.should_retry(j)


class TestSlaCancelled:
    def test_cancelled_stops_clock_and_does_not_breach_sla(self):
        j = _make_job(status=st.CANCELLED, sla_seconds=10, queued_at=0, ended_at=5)
        assert not sla.is_breached(j, 999_999), "Cancelled job must not breach SLA"

    def test_finished_at_returns_ended_at_for_cancelled(self):
        j = _make_job(status=st.CANCELLED, ended_at=42)
        assert sla.finished_at(j, 999) == 42


class TestSummaryCancelled:
    def test_cancelled_counts_in_own_bucket(self):
        jobs = [_make_job(status=st.CANCELLED)]
        counts = summary.counts(jobs)
        assert counts.get("cancelled") == 1, "Cancelled jobs must be in their own bucket"
        assert counts.get("other") == 0, "Cancelled jobs must not fall into 'other'"

    def test_failure_rate_excludes_cancelled_from_denominator(self):
        # With 1 done and 1 cancelled, failure rate should be 0.0 (no failures)
        jobs = [_make_job(status=st.DONE), _make_job(status=st.CANCELLED)]
        rate = summary.failure_rate(jobs)
        assert rate == 0.0, "Cancelled jobs must not inflate failure rate"

import pytest
from pipeline import ingest, constants, config


def test_uppercase_flag_not_dropped_as_bad_flag():
    settings = config.load()
    raw_records = [
        {"t_ms": 0, "channel": "temp_c", "value": 21.5, "flag": "OK", "device": "dev-a1"}
    ]
    accepted = ingest.accept(raw_records, settings)
    assert accepted.drops[constants.DROP_BAD_FLAG] == 0
    assert len(accepted.samples) == 1
